def pi(n):
    count = 0
    is_prime = [True] * (n + 1)
    if n >= 0:
        is_prime[0] = False
    if n >= 1:
        is_prime[1] = False
    for p in range(2, int(n**0.5) + 1):
        if is_prime[p]:
            for i in range(p*p, n + 1, p):
                is_prime[i] = False
    for i in range(2, n + 1):
        if is_prime[i]:
            count += 1
    return count

print(f"pi(40): {pi(40)}")
print(f"pi(41): {pi(41)}")

